              background-color: #f3f4f6;
              color: #1f2937;
            }
            * {
              box-sizing: border-box;
            }
          `}</style>
        </head>
        <body>
          <Outlet />
          <Scripts />
        </body>
      </html>
    </QueryClientProvider>
  )
}

